import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        Map<String, List<String>> acl = new LinkedHashMap<>();
        int n = in.nextInt();
        for (int j = 0; j < n; j++) {
            String sub = in.next();
            String obj = in.next();
            in.next();
            acl.computeIfAbsent(obj, k -> new ArrayList<>()).add(sub);
        }
        int q = in.nextInt();
        for (int j = 0; j < q; j++) {
            String obj = in.next();
            String javob = String.join(" ", acl.getOrDefault(obj, List.of()));
            System.out.println(javob.isEmpty() ? "-" : javob);
        }
    }
}

