#include <iostream>
#include <map>
#include <string>
#include <vector>
using namespace std;

int main() {
    map<string, vector<string>> acl;
    int n;
    cin >> n;
    for (int j = 0; j < n; j++) {
        string sub, obj, amal;
        cin >> sub >> obj >> amal;
        vector<string> royxat = acl[obj];
        bool bormi = false;
        for (size_t k = 0; k < royxat.size(); k++) {
            if (royxat[k] == sub) bormi = true;
        }
        if (!bormi) acl[obj].push_back(sub);
    }
    int q;
    cin >> q;
    for (int j = 0; j < q; j++) {
        string obj;
        cin >> obj;
        vector<string> royxat = acl[obj];
        if (royxat.empty()) {
            cout << "-" << endl;
            continue;
        }
        for (size_t k = 0; k < royxat.size(); k++) cout << (k ? " " : "") << royxat[k];
        cout << endl;
    }
    return 0;
}
